    pc = param_count(d)
    return (f"structure: layers={d['layers']} m={d['m']} params={pc['total']:,} "
            f"({100 * pc['fraction_of_full']:.1f}% of {FULL_PARAMS:,}; {100 * pc['reduction_vs_full']:.1f}% smaller)")

