import numpy as np
def folds(y, k=5, seed=0):
    rng = np.random.RandomState(seed); f = np.zeros(len(y), int)
    for c in np.unique(y):
        idx = np.where(y==c)[0]; rng.shuffle(idx)
        f[idx] = np.arange(len(idx)) % k
    return f
def ridge_fit(X, y, lam, nc=8):
    mu = X.mean(0); sd = X.std(0)+1e-6
    Z = (X-mu)/sd
    Y = np.eye(nc)[y]; Y = Y - Y.mean(0)
    n,d = Z.shape
    if d <= n:
        Wt = np.linalg.solve(Z.T@Z + lam*np.eye(d), Z.T@Y)
    else:
        Wt = Z.T @ np.linalg.solve(Z@Z.T + lam*np.eye(n), Y)
    return mu, sd, Wt
def ridge_pred(model, X):
    mu, sd, Wt = model
    return ((X-mu)/sd) @ Wt
def cv_acc(X, y, lams=(10,30,100,300,1000,3000), k=5, seeds=(0,), ret_scores=False):
    out = {}
    for lam in lams:
        accs=[]
        for s in seeds:
            f = folds(y,k,s); S = np.zeros((len(y),8))
            for i in range(k):
                tr = f!=i; te = f==i
                S[te] = ridge_pred(ridge_fit(X[tr], y[tr], lam), X[te])
            accs.append((S.argmax(1)==y).mean())
        out[lam] = float(np.mean(accs))
    return out
'''
