def ridge_fit(X, y, lam, nc=8):
    mu = X.mean(0); sd = X.std(0)+1e-6
    Z = (X-mu)/sd
    Y = np.eye(nc)[y]; Y = Y - Y.mean(0)
    n,d = Z.shape
    if d <= n:
        Wt = np.linalg.solve(Z.T@Z + lam*np.eye(d), Z.T@Y)
    else:
        Wt = Z.T @ np.linalg.solve(Z@Z.T + lam*np.eye(n), Y)
    return mu, sd, Wt
